shellCommands.command:
/bin/bash -lc "cat > src/index.css <<'EOF'
* { box-sizing: border-box; }
body { margin: 0; min-width: 320px; }
button, input, a { -webkit-tap-highlight-color: transparent; }
.page { min-height: 100svh; display: flex; flex-direction: column; color: var(--g-color-text-primary); background: var(--g-color-base-background); }
.page-header, .page-footer { display: flex; align-items: center; justify-content: space-between; padding-inline: calc(var(--g-spacing-10) + var(--g-spacing-4)); flex-shrink: 0; }
.page-header { height: 112px; }
.brand { flex-shrink: 0; }
.brand-name { letter-spacing: -1.1px; }
.brand-symbol { width: 34px; height: 34px; display: grid; place-items: center; background: var(--g-color-base-brand); border-radius: var(--g-border-radius-m); transform: rotate(-8deg); }
.brand-symbol > span { width: 19px; height: 19px; border: 5px solid var(--g-color-text-brand-contrast); border-radius: 50%; position: relative; }
.brand-symbol > span::after { content: ''; position: absolute; width: 9px; height: 5px; background: var(--g-color-text-brand-contrast); right: -7px; bottom: -4px; transform: rotate(44deg); }
.theme-button { --g-button-border-radius: var(--g-border-radius-m); flex-shrink: 0; }
.main-content { width: 100%; flex: 1; display: flex; flex-direction: column; align-items: center; justify-content: center; padding: var(--g-spacing-8) var(--g-spacing-6) var(--g-spacing-10); }
.login-shell { display: grid; grid-template-columns: 1fr 1.08fr; width: min(100%, 1080px); min-height: 612px; border: 1px solid var(--g-color-line-generic); border-radius: var(--g-border-radius-xl); overflow: hidden; box-shadow: 0 12px 44px -24px var(--g-color-sfx-shadow); }
.welcome-panel { position: relative; isolation: isolate; overflow: hidden; padding: calc(var(--g-spacing-10) + var(--g-spacing-2)); background: color-mix(in srgb, var(--g-color-base-brand) 13%, var(--g-color-base-background)); display: flex; flex-direction: column; }
.welcome-eyebrow { letter-spacing: 1.6px; }
.status-dot { width: 6px; height: 6px; background: var(--g-color-text-primary); border-radius: 50%; flex-shrink: 0; }
.welcome-title { margin: var(--g-spacing-8) 0 var(--g-spacing-4); letter-spacing: -1.5px; }
.title-dot { color: var(--g-color-text-brand); }
.welcome-description { margin: 0; line-height: 1.65; }
.welcome-footer { margin-top: auto; padding-top: var(--g-spacing-5); position: relative; z-index: 1; }
.mini-mark { font-size: 26px; flex-shrink: 0; }
.orbit-art { position: relative; width: 100%; height: 265px; margin-block: var(--g-spacing-3); }
.orbit { position: absolute; top: 50%; left: 50%; width: 340px; height: 190px; border: 1px solid color-mix(in srgb, var(--g-color-text-primary) 19%, transparent); border-radius: 50%; }
.orbit-one { transform: translate(-50%, -50%) rotate(-32deg); }
.orbit-two { transform: translate(-50%, -50%) rotate(32deg); }
.orbit-three { transform: translate(-50%, -50%) rotate(90deg); height: 160px; }
.orbit-axis { width: 1px; height: 285px; background: linear-gradient(transparent, var(--g-color-line-generic), transparent); position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%) rotate(32deg); }
.planet { position: absolute; width: 132px; height: 132px; top: 50%; left: 50%; transform: translate(-50%, -50%); border-radius: 50%; background: radial-gradient(circle at 30% 25%, color-mix(in srgb, var(--g-color-base-brand) 35%, var(--g-color-base-background)) 0%, var(--g-color-base-brand) 52%, color-mix(in srgb, var(--g-color-base-brand) 70%, var(--g-color-text-primary)) 100%); box-shadow: 12px 20px 36px -15px color-mix(in srgb, var(--g-color-base-brand) 50%, transparent), inset -8px -8px 18px color-mix(in srgb, var(--g-color-text-primary) 8%, transparent); }
.satellite { position: absolute; border-radius: 50%; }
.satellite-one { width: 21px; height: 21px; top: 42px; left: 71%; background: var(--g-color-text-primary); box-shadow: inset -4px -3px 5px var(--g-color-sfx-shadow); }
.satellite-two { width: 14px; height: 14px; bottom: 52px; left: 13%; background: var(--g-color-base-brand); }
.art-spark { position: absolute; color: var(--g-color-text-primary); font-size: 31px; font-weight: 300; }
.spark-one { right: 0; top: 47%; }
.spark-two { left: 9%; top: 8%; font-size: 24px; }
.art-dot { width: 4px; height: 4px; position: absolute; bottom: 24px; left: 62%; background: var(--g-color-text-primary); border-radius: 50%; }
.form-panel { display: flex; align-items: center; justify-content: center; padding: calc(var(--g-spacing-10) + var(--g-spacing-6)); min-width: 0; }
.form-content { width: 100%; max-width: 368px; }
.form-eyebrow { letter-spacing: 1.8px; margin-bottom: var(--g-spacing-4); }
.login-title { margin: 0 0 var(--g-spacing-3); letter-spacing: -1.1px; }
.login-description { margin: 0 0 var(--g-spacing-8); }
.field { margin-bottom: var(--g-spacing-5); }
.field-label { display: block; margin-bottom: var(--g-spacing-2); font-weight: 500; }
.password-field { margin-bottom: var(--g-spacing-6); }
.remember-checkbox { margin-bottom: var(--g-spacing-7); }
.login-button { --g-button-border-radius: var(--g-border-radius-m); font-weight: 500; }
.form-notice { margin-top: var(--g-spacing-4); }
.form-bottom { display: flex; flex-direction: column; align-items: center; gap: var(--g-spacing-5); margin-top: var(--g-spacing-8); text-align: center; }
.form-bottom-line { width: 100%; height: 1px; background: var(--g-color-line-generic); }
.under-card { margin: var(--g-spacing-6) 0 0; letter-spacing: .15px; }
.page-footer { min-height: 80px; padding-bottom: var(--g-spacing-4); gap: var(--g-spacing-4); }
.gravity-link { color: var(--g-color-text-secondary); text-decoration: none; display: flex; align-items: center; gap: var(--g-spacing-2); }
.gravity-link:hover { color: var(--g-color-text-primary); }
.gravity-link:focus-visible { outline: 2px solid var(--g-color-line-focus); outline-offset: 4px; border-radius: var(--g-border-radius-xs); }
@media (min-width: 1500px) { .login-shell { min-height: 650px; } }
@media (max-width: 1000px) {
  .page-header, .page-footer { padding-inline: var(--g-spacing-8); }
  .welcome-panel { padding: var(--g-spacing-8); }
  .form-panel { padding: var(--g-spacing-8); }
  .welcome-title { font-size: var(--g-text-display-1-font-size); line-height: var(--g-text-display-1-line-height); }
  .desktop-break { display: none; }
  .orbit { width: 290px; }
}
@media (max-width: 760px) {
  .page-header { height: 88px; }
  .header-caption { display: none; }
  .main-content { padding-top: var(--g-spacing-4); }
  .login-shell { grid-template-columns: 1fr; max-width: 480px; min-height: auto; }
  .welcome-panel { display: none; }
  .form-panel { padding: var(--g-spacing-10) var(--g-spacing-8); min-height: 530px; }
  .page-footer { padding-inline: var(--g-spacing-6); }
}
@media (max-width: 390px) {
  .page-header { padding-inline: var(--g-spacing-6); }
  .main-content { padding-inline: var(--g-spacing-4); }
  .form-panel { padding-inline: var(--g-spacing-6); }
  .login-title { letter-spacing: -1.3px; }
  .page-footer { gap: var(--g-spacing-2); }
}
EOF
npm run build"
